// The /exemple galleries: one batch per kind of render RenderBox makes.
//
// 2026-10-13 (owner): every image here was generated by the owner from our own
// prompts (PROMPTS-RENDERBOX.md) — nothing taken from the web — and the page
// shows every kind of render: the five ambiances of the command bar, two
// images each, then sketches next to their renders, then the four lights.
//
// The batch an image sits in is a claim about the image (what the light does,
// what kind of drawing it is), so it has to stay true if you swap one.
//
// Each image carries its real pixel size: the page shows it whole, never
// cropped, and lays a row out so that its images share one height (see
// rowColumns). TO ADD ONE: drop a JPG in `frontend/public/galerie/` and add
// it to the right row with its width and height. Served from /public because
// the site CSP only allows the site's own images (and the films' origin).
import type { PresetKey } from '@/lib/server/generation/presets';

export interface GalleryImage {
  src: string;
  w: number;
  h: number;
}

export interface GalleryBatch {
  /** A preset's key (its name comes from presets.ts) or a batch of our own. */
  key: PresetKey | 'croquis';
  /** Only for a batch that is not a preset. */
  label?: { fr: string; en: string };
  /** One row per line on a computer; on a phone every image stacks. */
  rows: readonly (readonly GalleryImage[])[];
}

const L = (src: string): GalleryImage => ({ src, w: 1200, h: 896 });
const P = (src: string): GalleryImage => ({ src, w: 760, h: 1013 });

