/**
 * The CSS columns that give a row's images one shared height: each column's
 * share is its image's width-to-height ratio.
 */
export function rowColumns(row: readonly GalleryImage[]): string {
  return row.map((img) => `${(img.w / img.h).toFixed(4)}fr`).join(' ');
}

/** Every gallery image, flat and without duplicates, in page order. */
export const GALLERY_IMAGES: readonly string[] = [
  ...new Set(GALLERY.flatMap((b) => b.rows.flat().map((img) => img.src))),
];
